def patch_simple_worker(source):
    if not isinstance(source, str):
        raise RuntimeError('Workerbron moet tekst zijn')
    if MARKER in source:
        if source.count(MARKER) != 1 or hashlib.sha256(source.encode()).hexdigest() != PATCHED_WORKER_SHA256:
            raise RuntimeError('Bestaande vereenvoudigingspatch wijkt af; geen wijziging')
        compile(source, '<simple-worker-existing>', 'exec')
        return source
    if hashlib.sha256(source.encode()).hexdigest() != BASE_WORKER_SHA256:
        raise RuntimeError('Worker wijkt af van de beoordeelde bestaande versie')
    tree = ast.parse(source)
    functions = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
    if not {'prepare','patch_api'}.issubset(functions):
        raise RuntimeError('Verwachte voorbereidings- of APIhook ontbreekt')
    prepare = functions['prepare']
    changes = {'schema': 0, 'definitions': 0, 'snapshot': 0, 'log': 0}
    output = []
    for statement in prepare.body:
        output.append(statement)
        if isinstance(statement, ast.Assign) and len(statement.targets) == 1 and isinstance(statement.targets[0], ast.Name):
            target = statement.targets[0].id
            if target == 'schema' and isinstance(statement.value, ast.Call) and isinstance(statement.value.func, ast.Name) and statement.value.func.id == '_bc_add_variant_schema':
                output.extend(ast.parse('schema = _bc_simple_schema(schema)').body); changes['schema'] += 1
            if target == 'definitions':
                output.extend(ast.parse('definitions = _bc_simple_definitions(definitions)').body); changes['definitions'] += 1
            if target == 'snapshot':
                output.extend(ast.parse('_bc_simple_snapshot(snapshot, docs)').body); changes['snapshot'] += 1
        if isinstance(statement, ast.Expr) and isinstance(statement.value, ast.Call) and isinstance(statement.value.func, ast.Name) and statement.value.func.id == 'log':
            text = ast.unparse(statement)
            if 'PVD blijft apart' in text:
                output[-1] = ast.parse("log('Basiskleuren en gepaarde tegelformaten afgeleid; exacte bronwaarden behouden.')").body[0]
                changes['log'] += 1
    prepare.body = output
    if changes != {'schema': 1, 'definitions': 1, 'snapshot': 1, 'log': 1}:
        raise RuntimeError('Niet alle vereenvoudigingshooks gevonden')
    api = functions['patch_api']
    api.body = ast.parse("if '# BC_FILTER_SIMPLIFICATION_V1' in source:\n    return patch_simple_api(source)\nreturn patch_simple_api(patch_variant_api(patch_rvs_api(patch_b2c_api(patch_generation_api(source)))))").body
    ast.fix_missing_locations(tree)
    # Replace only two reviewed functions so unrelated source stays byte-identical.
    lines = source.splitlines(keepends=True)
    replacements = []
    for node in (prepare, api):
        start = sum(len(s) for s in lines[:node.lineno-1])
        end = sum(len(s) for s in lines[:node.end_lineno])
        replacements.append((start,end,ast.unparse(node)+'\n'))
    result = source
    for start,end,text in sorted(replacements, reverse=True):
        result = result[:start] + text + result[end:]
    result_tree = ast.parse(result)
    guards = [n for n in result_tree.body if isinstance(n, ast.If) and '__name__' in ast.unparse(n.test)]
    if len(guards) != 1:
        raise RuntimeError('Geen unieke workerstartguard')
    lines = result.splitlines(keepends=True)
    position = sum(len(s) for s in lines[:guards[0].lineno-1])
    prelude = MARKER + '\n_BC_SIMPLE_COLORS = {"__name__": "bc_simple_colors_embedded"}\nexec(compile(' + repr(COLOR_SOURCE) + ', "<derived-color-rules>", "exec"), _BC_SIMPLE_COLORS)\n'
    prelude += '_BC_SIMPLE_ENUM_ALIASES = ' + repr(TYPE_ALIASES) + '\n_BC_SIMPLE_TYPE_LABELS = _BC_SIMPLE_ENUM_ALIASES["f_productsoort"]\n'
    prelude += RUNTIME_SOURCE.rstrip() + '\n\n'
    result = result[:position] + prelude + result[position:]
    compile(result, '<simple-worker>', 'exec')
    return result
